void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await AppDb.instance.ensureCompany();
  runApp(const OfflineErpApp());
}

class OfflineErpApp extends StatelessWidget {
  const OfflineErpApp({super.key});
  @override
  Widget build(BuildContext context) => MaterialApp(
    debugShowCheckedModeBanner: false,
    title: 'Offline ERP',
    theme: ThemeData(useMaterial3: true, colorSchemeSeed: Colors.indigo, brightness: Brightness.light),
    darkTheme: ThemeData(useMaterial3: true, colorSchemeSeed: Colors.indigo, brightness: Brightness.dark),
    home: const Shell(),
  );
}

class Shell extends StatefulWidget { const Shell({super.key}); @override State<Shell> createState()=>_ShellState(); }
class _ShellState extends State<Shell> {
  int index=0; final db=AppDb.instance;
  final titles=['Dashboard','Accounting / Ledgers','Inventory','Sales Invoices','Purchase Bills','Vouchers','Banking','Reports','Payroll','GST / Tax','Settings'];
  void refresh(){setState((){});}
  @override Widget build(BuildContext context){
    final pages=[
      DashboardPage(onRefresh:refresh),
      LedgerPage(onRefresh:refresh),
      InventoryPage(onRefresh:refresh),
      SalesPage(onRefresh:refresh),
      PurchasePage(onRefresh:refresh),
      VoucherPage(onRefresh:refresh),
      BankingPage(onRefresh:refresh),
      ReportsPage(),
      PayrollPage(onRefresh:refresh),
      GstPage(onRefresh:refresh),
      SettingsPage(onRefresh:refresh),
    ];
    return Scaffold(
      appBar: AppBar(title: Text(titles[index]), actions:[IconButton(onPressed:()=>showSearch(context:context,delegate:ErpSearchDelegate()),icon:const Icon(Icons.search))]),
      drawer: Drawer(child:SafeArea(child:ListView(padding:EdgeInsets.zero,children:[
        DrawerHeader(decoration:BoxDecoration(color:Theme.of(context).colorScheme.primaryContainer),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(Icons.account_balance,size:42),const SizedBox(height:10),FutureBuilder<List<Map<String,Object?>>>(future:db.query('companies'),builder:(c,s){final n=s.data?.isNotEmpty==true?s.data!.first['name']:'Offline ERP';return Text('$n',style:Theme.of(context).textTheme.titleLarge);}),const Text('Offline-first • SQLite')]),),
        for(int i=0;i<titles.length;i++) ListTile(selected:index==i,leading:Icon(_icons[i]),title:Text(titles[i]),onTap:(){Navigator.pop(context);setState(()=>index=i);}),
      ]))),
      body: IndexedStack(index:index,children:pages),
    );
  }
  static const _icons=[Icons.dashboard,Icons.account_balance_wallet,Icons.inventory_2,Icons.point_of_sale,Icons.shopping_cart,Icons.receipt_long,Icons.account_balance,Icons.analytics,Icons.people,Icons.receipt,Icons.settings];
}

class ErpSearchDelegate extends SearchDelegate<String>{
  @override List<Widget>? buildActions(BuildContext context)=>[IconButton(onPressed:()=>query='',icon:const Icon(Icons.clear))];
  @override Widget? buildLeading(BuildContext context)=>IconButton(onPressed:()=>close(context,''),icon:const Icon(Icons.arrow_back));
  @override Widget buildResults(BuildContext context)=>FutureBuilder<List<Map<String,Object?>>>(future:AppDb.instance.query('ledgers',where:'name LIKE ?',args:['%$query%'],limit:30),builder:(c,s){final rows=s.data??[];return ListView(children:rows.map((r)=>ListTile(title:Text('${r['name']}'),subtitle:Text('Ledger • ${r['gstin']??''}'))).toList());});
  @override Widget buildSuggestions(BuildContext context)=>buildResults(context);
}

String money(Object? n){final v=(n as num?)?.toDouble()??0;return NumberFormat.currency(locale:'en_IN',symbol:'₹',decimalDigits:2).format(v);}
String dateText(Object? v){if(v==null)return '';return DateFormat('dd-MM-yyyy').format(DateTime.tryParse('$v')??DateTime.now());}
Future<String> cid()=>AppDb.instance.ensureCompany();

class DashboardPage extends StatelessWidget{
  final VoidCallback onRefresh; const DashboardPage({super.key,required this.onRefresh});
  @override Widget build(BuildContext context)=>FutureBuilder<Map<String,Object?>>(future:cid().then((id)=>AppDb.instance.summary(id)),builder:(c,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());final x=s.data??{};return RefreshIndicator(onRefresh:()async{onRefresh();},child:ListView(padding:const EdgeInsets.all(16),children:[
    Text('Business overview',style:Theme.of(context).textTheme.headlineSmall),const SizedBox(height:16),
    GridView.count(crossAxisCount:MediaQuery.of(context).size.width>700?4:2,shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),crossAxisSpacing:12,mainAxisSpacing:12,childAspectRatio:1.6,children:[
      StatCard('Sales',money(x['sales']),Icons.trending_up),StatCard('Purchases',money(x['purchase']),Icons.shopping_cart),StatCard('Stock Qty',(x['stock']??0).toString(),Icons.inventory_2),StatCard('Customers','${x['customers']??0}',Icons.people),
    ]),const SizedBox(height:20),
    Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Quick actions',style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:10),Wrap(spacing:10,runSpacing:10,children:[
      FilledButton.icon(onPressed:()=>_quick(context,'Sales Invoice'),icon:const Icon(Icons.add_shopping_cart),label:const Text('Sales Invoice')),
      OutlinedButton.icon(onPressed:()=>_quick(context,'Purchase Bill'),icon:const Icon(Icons.add_business),label:const Text('Purchase Bill')),
      OutlinedButton.icon(onPressed:()=>_quick(context,'Receipt'),icon:const Icon(Icons.payments),label:const Text('Receipt')),
      OutlinedButton.icon(onPressed:()=>_quick(context,'Payment'),icon:const Icon(Icons.payment),label:const Text('Payment')),
    ])]))),const SizedBox(height:20),
    Card(child:ListTile(leading:const Icon(Icons.offline_bolt),title:const Text('Offline mode'),subtitle:const Text('All business data is stored locally on this phone. Use Settings → Backup before changing phones.'))),
  ]));});
  Future<void> _quick(BuildContext context,String type) async {if(type=='Sales Invoice'){await showDialog(context:context,builder:(_)=>SalesDialog(onSaved:onRefresh));}else if(type=='Purchase Bill'){await showDialog(context:context,builder:(_)=>PurchaseDialog(onSaved:onRefresh));}else{await showDialog(context:context,builder:(_)=>VoucherDialog(kind:type,onSaved:onRefresh));}}
