class LedgerDialog extends StatefulWidget{final VoidCallback onSaved;const LedgerDialog({super.key,required this.onSaved});@override State<LedgerDialog> createState()=>_LedgerDialogState();}
class _LedgerDialogState extends State<LedgerDialog>{final name=TextEditingController(),gst=TextEditingController(),phone=TextEditingController(),opening=TextEditingController();String? group;bool customer=false,supplier=false;List<Map<String,Object?>> groups=[];
  @override void initState(){super.initState();AppDb.instance.query('account_groups',orderBy:'name').then((v){if(mounted)setState((){groups=v;group=v.isNotEmpty?v.first['id'] as String:null;});});}
  @override Widget build(BuildContext c)=>AlertDialog(title:const Text('Create Ledger'),content:SizedBox(width:520,child:SingleChildScrollView(child:Column(children:[field(name,'Ledger name'),DropdownButtonFormField<String>(value:group,items:groups.map((g)=>DropdownMenuItem(value:g['id'] as String,child:Text(g['name'] as String))).toList(),onChanged:(v)=>setState(()=>group=v),decoration:const InputDecoration(labelText:'Group',border:OutlineInputBorder())),field(gst,'GSTIN (optional)'),field(phone,'Phone'),field(opening,'Opening balance',keyboard:TextInputType.number),SwitchListTile(title:const Text('Customer'),value:customer,onChanged:(v)=>setState(()=>customer=v)),SwitchListTile(title:const Text('Supplier'),value:supplier,onChanged:(v)=>setState(()=>supplier=v))])),),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancel')),FilledButton(onPressed:save,child:const Text('Save'))]);
  Widget field(TextEditingController x,String label,{TextInputType? keyboard})=>Padding(padding:const EdgeInsets.only(bottom:10),child:TextField(controller:x,keyboardType:keyboard,decoration:InputDecoration(labelText:label,border:const OutlineInputBorder())));
  Future<void> save()async{if(name.text.trim().isEmpty)return;final id=AppDb.instance.id();final company=await cid();await AppDb.instance.insert('ledgers',{'id':id,'company_id':company,'group_id':group,'name':name.text.trim(),'gstin':gst.text.trim(),'phone':phone.text.trim(),'opening_balance':double.tryParse(opening.text)??0,'opening_type':'Dr','is_customer':customer?1:0,'is_supplier':supplier?1:0});await AppDb.instance.audit(company,'ledgers',id,'CREATE',newData:{'name':name.text.trim()});widget.onSaved();if(mounted)Navigator.pop(context);}
}

