class _ItemDialogState extends State<ItemDialog>{final name=TextEditingController(),sku=TextEditingController(),hsn=TextEditingController(),gst=TextEditingController(),qty=TextEditingController(),rate=TextEditingController();String? unit,warehouse;
@override Widget build(BuildContext c)=>FutureBuilder<List<Map<String,Object?>>>(future:Future.wait([AppDb.instance.query('units'),AppDb.instance.query('warehouses')]),builder:(c,s){final units=s.data?[0]??[];final wh=s.data?[1]??[];unit??=units.isNotEmpty?units.first['id'] as String:null;warehouse??=wh.isNotEmpty?wh.first['id'] as String:null;return AlertDialog(title:const Text('Stock Item'),content:SizedBox(width:540,child:SingleChildScrollView(child:Column(children:[f(name,'Item name'),f(sku,'SKU'),f(hsn,'HSN/SAC'),f(gst,'GST %',num:true),f(qty,'Opening quantity',num:true),f(rate,'Opening rate',num:true),DropdownButtonFormField<String>(value:unit,items:units.map((x)=>DropdownMenuItem(value:x['id'] as String,child:Text('${x['name']} (${x['symbol']})'))).toList(),onChanged:(v)=>setState(()=>unit=v),decoration:const InputDecoration(labelText:'Unit',border:OutlineInputBorder())),DropdownButtonFormField<String>(value:warehouse,items:wh.map((x)=>DropdownMenuItem(value:x['id'] as String,child:Text(x['name'] as String))).toList(),onChanged:(v)=>setState(()=>warehouse=v),decoration:const InputDecoration(labelText:'Opening warehouse',border:OutlineInputBorder()))]))),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancel')),FilledButton(onPressed:save,child:const Text('Save'))]);});
Widget f(TextEditingController x,String l,{bool num=false})=>Padding(padding:const EdgeInsets.only(bottom:9),child:TextField(controller:x,keyboardType:num?TextInputType.number:null,decoration:InputDecoration(labelText:l,border:const OutlineInputBorder())));
