class TransactionList extends StatelessWidget{final String table,dateField,numberField,title,button;final Widget Function() dialogBuilder;const TransactionList({super.key,required this.table,required this.dateField,required this.numberField,required this.title,required this.button,required this.dialogBuilder});@override Widget build(BuildContext c)=>FutureBuilder<List<Map<String,Object?>>>(future:AppDb.instance.query(table,orderBy:'$dateField DESC'),builder:(c,s){final rows=s.data??[];return Column(children:[Padding(padding:const EdgeInsets.all(16),child:Row(children:[Text(title,style:Theme.of(c).textTheme.titleLarge),const Spacer(),FilledButton.icon(onPressed:()=>showDialog(context:c,builder:(_)=>dialogBuilder()),icon:const Icon(Icons.add),label:Text(button))])),Expanded(child:ListView.builder(itemCount:rows.length,itemBuilder:(c,i){final r=rows[i];return Card(margin:const EdgeInsets.symmetric(horizontal:16,vertical:4),child:ListTile(title:Text('${r[numberField]}'),subtitle:Text(dateText(r[dateField])),trailing:Text(money(r['grand_total']))));}))]);});}

class SalesDialog extends StatefulWidget{final VoidCallback onSaved;const SalesDialog({super.key,required this.onSaved});@override State<SalesDialog> createState()=>_SalesDialogState();}
class _SalesDialogState extends State<SalesDialog>{String? customer,item,warehouse;final qty=TextEditingController(text:'1'),rate=TextEditingController(text:'0'),discount=TextEditingController(text:'0'),gst=TextEditingController(text:'18');bool interstate=false;List<Map<String,Object?>> customers=[],items=[],warehouses=[];
@override Widget build(BuildContext c)=>FutureBuilder<List<List<Map<String,Object?>>>>(future:Future.wait([AppDb.instance.query('ledgers',where:'is_customer=1',orderBy:'name'),AppDb.instance.query('stock_items',orderBy:'name'),AppDb.instance.query('warehouses',orderBy:'name')]),builder:(c,s){if(s.connectionState!=ConnectionState.done)return const AlertDialog(content:SizedBox(height:100,child:Center(child:CircularProgressIndicator())));customers=s.data![0];items=s.data![1];warehouses=s.data![2];customer??=customers.isNotEmpty?customers.first['id'] as String:null;item??=items.isNotEmpty?items.first['id'] as String:null;warehouse??=warehouses.isNotEmpty?warehouses.first['id'] as String:null;return AlertDialog(title:const Text('Sales Invoice'),content:SizedBox(width:580,child:SingleChildScrollView(child:Column(children:[dd('Customer',customer,customers,'name'),dd('Item',item,items,'name'),dd('Warehouse',warehouse,warehouses,'name'),numf(qty,'Quantity'),numf(rate,'Rate'),numf(discount,'Discount %'),numf(gst,'GST %'),SwitchListTile(title:const Text('Inter-state (IGST)'),value:interstate,onChanged:(v)=>setState(()=>interstate=v)),ValueListenableBuilder<TextEditingValue>(valueListenable:qty,builder:(_,__,___)=>_totals())]))),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancel')),FilledButton(onPressed:save,child:const Text('Post Invoice'))]);});
Widget dd(String label,String? value,List<Map<String,Object?>> rows,String field)=>Padding(padding:const EdgeInsets.only(bottom:9),child:DropdownButtonFormField<String>(value:value,items:rows.map((r)=>DropdownMenuItem(value:r['id'] as String,child:Text('${r[field]}'))).toList(),onChanged:(v){setState((){if(label=='Customer')customer=v;if(label=='Item')item=v;if(label=='Warehouse')warehouse=v;});},decoration:InputDecoration(labelText:label,border:const OutlineInputBorder())));
Widget numf(TextEditingController x,String l)=>Padding(padding:const EdgeInsets.only(bottom:9),child:TextField(controller:x,keyboardType:TextInputType.number,decoration:InputDecoration(labelText:l,border:const OutlineInputBorder()),onChanged:(_)=>setState((){})));
Widget _totals(){final q=double.tryParse(qty.text)??0,r=double.tryParse(rate.text)??0,d=double.tryParse(discount.text)??0,g=double.tryParse(gst.text)??0;final taxable=q*r*(1-d/100),tax=taxable*g/100,total=taxable+tax;return Align(alignment:Alignment.centerRight,child:Text('Taxable ${money(taxable)}   GST ${money(tax)}   Total ${money(total)}',style:const TextStyle(fontWeight:FontWeight.bold)));}
Future<void> save()async{if(customer==null||item==null||warehouse==null)return;final company=await cid();final d=AppDb.instance;final q=double.tryParse(qty.text)??0,r=double.tryParse(rate.text)??0,disc=double.tryParse(discount.text)??0,g=double.tryParse(gst.text)??0;final taxable=q*r*(1-disc/100),tax=taxable*g/100,cgst=interstate?0:tax/2,sgst=interstate?0:tax/2,igst=interstate?tax:0,total=taxable+tax;final invoiceId=d.id();final no=await d.nextVoucherNo(company,'SI');final vType=await _voucherType(company,'SI');await d.transaction((tx)async{final vId=d.id();final sales=await _ledgerId(company,'Sales');final outC=await _ledgerId(company,'Output CGST');final outS=await _ledgerId(company,'Output SGST');final outI=await _ledgerId(company,'Output IGST');await tx.insert('vouchers',{'id':vId,'company_id':company,'voucher_type_id':vType,'voucher_no':no,'voucher_date':DateTime.now().toIso8601String(),'narration':'Sales invoice $no','created_at':DateTime.now().toIso8601String()});await tx.insert('voucher_entries',{'id':d.id(),'voucher_id':vId,'ledger_id':customer,'debit':total,'credit':0});await tx.insert('voucher_entries',{'id':d.id(),'voucher_id':vId,'ledger_id':sales,'debit':0,'credit':taxable});if(cgst>0){await tx.insert('voucher_entries',{'id':d.id(),'voucher_id':vId,'ledger_id':outC,'debit':0,'credit':cgst});await tx.insert('voucher_entries',{'id':d.id(),'voucher_id':vId,'ledger_id':outS,'debit':0,'credit':sgst});}if(igst>0)await tx.insert('voucher_entries',{'id':d.id(),'voucher_id':vId,'ledger_id':outI,'debit':0,'credit':igst});await tx.insert('sales_invoices',{'id':invoiceId,'company_id':company,'voucher_id':vId,'customer_id':customer,'invoice_no':no,'invoice_date':DateTime.now().toIso8601String(),'taxable_amount':taxable,'subtotal':q*r,'discount_amount':q*r*disc/100,'cgst_amount':cgst,'sgst_amount':sgst,'igst_amount':igst,'grand_total':total});await tx.insert('sales_invoice_items',{'id':d.id(),'invoice_id':invoiceId,'stock_item_id':item,'warehouse_id':warehouse,'quantity':q,'rate':r,'discount_percent':disc,'discount_amount':q*r*disc/100,'taxable_amount':taxable,'gst_rate':g,'cgst_amount':cgst,'sgst_amount':sgst,'igst_amount':igst,'total_amount':total});await tx.insert('stock_movements',{'id':d.id(),'company_id':company,'stock_item_id':item,'warehouse_id':warehouse,'movement_date':DateTime.now().toIso8601String(),'reference_type':'SALES','reference_id':invoiceId,'quantity_out':q,'rate':r});});widget.onSaved();if(mounted){Navigator.pop(context);await printInvoice(invoiceId);}}
}

class PurchaseDialog extends StatefulWidget{final VoidCallback onSaved;const PurchaseDialog({super.key,required this.onSaved});@override State<PurchaseDialog> createState()=>_PurchaseDialogState();}
class _PurchaseDialogState extends State<PurchaseDialog>{String? supplier,item,warehouse;final qty=TextEditingController(text:'1'),rate=TextEditingController(text:'0'),discount=TextEditingController(text:'0'),gst=TextEditingController(text:'18');bool interstate=false;List<Map<String,Object?>> suppliers=[],items=[],warehouses=[];
@override Widget build(BuildContext c)=>FutureBuilder<List<List<Map<String,Object?>>>>(future:Future.wait([AppDb.instance.query('ledgers',where:'is_supplier=1',orderBy:'name'),AppDb.instance.query('stock_items',orderBy:'name'),AppDb.instance.query('warehouses',orderBy:'name')]),builder:(c,s){if(s.connectionState!=ConnectionState.done)return const AlertDialog(content:SizedBox(height:100,child:Center(child:CircularProgressIndicator())));suppliers=s.data![0];items=s.data![1];warehouses=s.data![2];supplier??=suppliers.isNotEmpty?suppliers.first['id'] as String:null;item??=items.isNotEmpty?items.first['id'] as String:null;warehouse??=warehouses.isNotEmpty?warehouses.first['id'] as String:null;return AlertDialog(title:const Text('Purchase Bill'),content:SizedBox(width:580,child:SingleChildScrollView(child:Column(children:[dd('Supplier',supplier,suppliers),dd('Item',item,items),dd('Warehouse',warehouse,warehouses),numf(qty,'Quantity'),numf(rate,'Rate'),numf(discount,'Discount %'),numf(gst,'GST %'),SwitchListTile(title:const Text('Inter-state (IGST)'),value:interstate,onChanged:(v)=>setState(()=>interstate=v)),Text('Total ${money(_total())}',style:const TextStyle(fontWeight:FontWeight.bold))]))),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancel')),FilledButton(onPressed:save,child:const Text('Post Bill'))]);});
Widget dd(String label,String? value,List<Map<String,Object?>> rows)=>Padding(padding:const EdgeInsets.only(bottom:9),child:DropdownButtonFormField<String>(value:value,items:rows.map((r)=>DropdownMenuItem(value:r['id'] as String,child:Text('${r['name']}'))).toList(),onChanged:(v){setState((){if(label=='Supplier')supplier=v;if(label=='Item')item=v;if(label=='Warehouse')warehouse=v;});},decoration:InputDecoration(labelText:label,border:const OutlineInputBorder())));
Widget numf(TextEditingController x,String l)=>Padding(padding:const EdgeInsets.only(bottom:9),child:TextField(controller:x,keyboardType:TextInputType.number,decoration:InputDecoration(labelText:l,border:const OutlineInputBorder()),onChanged:(_)=>setState((){})));
double _total(){final q=double.tryParse(qty.text)??0,r=double.tryParse(rate.text)??0,d=double.tryParse(discount.text)??0,g=double.tryParse(gst.text)??0;final t=q*r*(1-d/100);return t+t*g/100;}
Future<void> save()async{if(supplier==null||item==null||warehouse==null)return;final company=await cid();final d=AppDb.instance;final q=double.tryParse(qty.text)??0,r=double.tryParse(rate.text)??0,disc=double.tryParse(discount.text)??0,g=double.tryParse(gst.text)??0;final taxable=q*r*(1-disc/100),tax=taxable*g/100,cgst=interstate?0:tax/2,sgst=interstate?0:tax/2,igst=interstate?tax:0,total=taxable+tax;final billId=d.id();final no=await d.nextVoucherNo(company,'PB');final vType=await _voucherType(company,'PB');await d.transaction((tx)async{final vId=d.id();final purchase=await _ledgerId(company,'Purchase');final inC=await _ledgerId(company,'Input CGST');final inS=await _ledgerId(company,'Input SGST');final inI=await _ledgerId(company,'Input IGST');await tx.insert('vouchers',{'id':vId,'company_id':company,'voucher_type_id':vType,'voucher_no':no,'voucher_date':DateTime.now().toIso8601String(),'narration':'Purchase bill $no','created_at':DateTime.now().toIso8601String()});await tx.insert('voucher_entries',{'id':d.id(),'voucher_id':vId,'ledger_id':purchase,'debit':taxable,'credit':0});if(cgst>0){await tx.insert('voucher_entries',{'id':d.id(),'voucher_id':vId,'ledger_id':inC,'debit':cgst,'credit':0});await tx.insert('voucher_entries',{'id':d.id(),'voucher_id':vId,'ledger_id':inS,'debit':sgst,'credit':0});}if(igst>0)await tx.insert('voucher_entries',{'id':d.id(),'voucher_id':vId,'ledger_id':inI,'debit':igst,'credit':0});await tx.insert('voucher_entries',{'id':d.id(),'voucher_id':vId,'ledger_id':supplier,'debit':0,'credit':total});await tx.insert('purchase_bills',{'id':billId,'company_id':company,'voucher_id':vId,'supplier_id':supplier,'bill_no':no,'bill_date':DateTime.now().toIso8601String(),'taxable_amount':taxable,'subtotal':q*r,'discount_amount':q*r*disc/100,'cgst_amount':cgst,'sgst_amount':sgst,'igst_amount':igst,'grand_total':total});await tx.insert('purchase_bill_items',{'id':d.id(),'purchase_bill_id':billId,'stock_item_id':item,'warehouse_id':warehouse,'quantity':q,'rate':r,'discount_amount':q*r*disc/100,'taxable_amount':taxable,'gst_rate':g,'cgst_amount':cgst,'sgst_amount':sgst,'igst_amount':igst,'total_amount':total});await tx.insert('stock_movements',{'id':d.id(),'company_id':company,'stock_item_id':item,'warehouse_id':warehouse,'movement_date':DateTime.now().toIso8601String(),'reference_type':'PURCHASE','reference_id':billId,'quantity_in':q,'rate':r});});widget.onSaved();if(mounted)Navigator.pop(context);}
}

