@override Widget build(BuildContext c)=>FutureBuilder<List<Map<String,Object?>>>(future:AppDb.instance.query('ledgers',orderBy:'name'),builder:(c,s){ledgers=s.data??[];debit??=ledgers.isNotEmpty?ledgers.first['id'] as String:null;credit??=ledgers.length>1?ledgers[1]['id'] as String:null;return AlertDialog(title:Text(widget.kind),content:SizedBox(width:520,child:Column(mainAxisSize:MainAxisSize.min,children:[dd('Debit',debit,(v)=>setState(()=>debit=v)),dd('Credit',credit,(v)=>setState(()=>credit=v)),TextField(controller:amount,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Amount',border:OutlineInputBorder())),const SizedBox(height:10),TextField(controller:narration,decoration:const InputDecoration(labelText:'Narration',border:OutlineInputBorder()))])),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancel')),FilledButton(onPressed:save,child:const Text('Post'))]);});
