Future<void> save()async{final a=double.tryParse(amount.text)??0;if(a<=0||debit==null||credit==null||debit==credit)return;final company=await cid();final d=AppDb.instance;final code={'Receipt':'RC','Payment':'PM','Contra':'CN','Journal':'JV'}[widget.kind]!;final no=await d.nextVoucherNo(company,code);final vType=await _voucherType(company,code);await d.transaction((tx)async{final v=d.id();await tx.insert('vouchers',{'id':v,'company_id':company,'voucher_type_id':vType,'voucher_no':no,'voucher_date':DateTime.now().toIso8601String(),'narration':narration.text,'created_at':DateTime.now().toIso8601String()});await tx.insert('voucher_entries',{'id':d.id(),'voucher_id':v,'ledger_id':debit,'debit':a,'credit':0,'narration':narration.text});await tx.insert('voucher_entries',{'id':d.id(),'voucher_id':v,'ledger_id':credit,'debit':0,'credit':a,'narration':narration.text});});widget.onSaved();if(mounted)Navigator.pop(context);}
