class ReportsPage extends StatefulWidget{const ReportsPage({super.key});@override State<ReportsPage> createState()=>_ReportsPageState();}
class _ReportsPageState extends State<ReportsPage>{String report='Day Book';
@override Widget build(BuildContext c)=>Column(children:[Padding(padding:const EdgeInsets.all(16),child:DropdownButtonFormField<String>(value:report,items:const ['Day Book','Ledger Summary','Trial Balance','Profit & Loss','Balance Sheet','Stock Summary','Receivables','Payables'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>setState(()=>report=v!),decoration:const InputDecoration(labelText:'Report',border:OutlineInputBorder()))),Expanded(child:_body())]);
Widget _body()=>FutureBuilder<List<Map<String,Object?>>>(future:_data(),builder:(c,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());final rows=s.data??[];return ListView(padding:const EdgeInsets.all(16),children:[Text(report,style:Theme.of(context).textTheme.headlineSmall),const SizedBox(height:10),if(rows.isEmpty)const Card(child:Padding(padding:EdgeInsets.all(20),child:Text('No data yet.')),),...rows.map((r)=>Card(child:ListTile(title:Text(_title(r)),trailing:Text(_amount(r)))))]);});
String _title(Map<String,Object?> r)=>'${r['name']??r['voucher_no']??r['invoice_no']??r['bill_no']??r['item']??''}';String _amount(Map<String,Object?> r)=>money(r['balance']??r['amount']??r['grand_total']??r['net']??r['qty']);
Future<List<Map<String,Object?>>> _data()async{final d=AppDb.instance;final company=await cid();switch(report){case 'Day Book':return d.query('vouchers',where:'company_id=?',args:[company],orderBy:'voucher_date DESC',limit:200);case 'Ledger Summary':return d.db.then((x)=>x.rawQuery('SELECT l.name, COALESCE(SUM(ve.debit),0)-COALESCE(SUM(ve.credit),0) balance FROM ledgers l LEFT JOIN voucher_entries ve ON ve.ledger_id=l.id WHERE l.company_id=? GROUP BY l.id ORDER BY l.name',[company]));case 'Trial Balance':return d.db.then((x)=>x.rawQuery('SELECT l.name, COALESCE(SUM(ve.debit),0) debit, COALESCE(SUM(ve.credit),0) credit FROM ledgers l LEFT JOIN voucher_entries ve ON ve.ledger_id=l.id WHERE l.company_id=? GROUP BY l.id ORDER BY l.name',[company]));case 'Profit & Loss':return d.db.then((x)=>x.rawQuery("SELECT l.name, CASE WHEN g.nature='INCOME' THEN COALESCE(SUM(ve.credit-ve.debit),0) ELSE COALESCE(SUM(ve.debit-ve.credit),0) END net FROM ledgers l JOIN account_groups g ON g.id=l.group_id LEFT JOIN voucher_entries ve ON ve.ledger_id=l.id WHERE l.company_id=? AND g.nature IN ('INCOME','EXPENSE') GROUP BY l.id ORDER BY l.name",[company]));case 'Balance Sheet':return d.db.then((x)=>x.rawQuery("SELECT l.name, CASE WHEN g.nature='LIABILITY' OR g.nature='EQUITY' THEN COALESCE(SUM(ve.credit-ve.debit),0) ELSE COALESCE(SUM(ve.debit-ve.credit),0) END balance FROM ledgers l JOIN account_groups g ON g.id=l.group_id LEFT JOIN voucher_entries ve ON ve.ledger_id=l.id WHERE l.company_id=? AND g.nature IN ('ASSET','LIABILITY','EQUITY') GROUP BY l.id ORDER BY l.name",[company]));case 'Stock Summary':return d.db.then((x)=>x.rawQuery('SELECT s.name item, COALESCE(SUM(sm.quantity_in-sm.quantity_out),0) qty FROM stock_items s LEFT JOIN stock_movements sm ON sm.stock_item_id=s.id WHERE s.company_id=? GROUP BY s.id ORDER BY s.name',[company]));case 'Receivables':return d.db.then((x)=>x.rawQuery("SELECT l.name, COALESCE(SUM(ve.debit-ve.credit),0) balance FROM ledgers l LEFT JOIN voucher_entries ve ON ve.ledger_id=l.id WHERE l.company_id=? AND l.is_customer=1 GROUP BY l.id HAVING balance<>0 ORDER BY l.name",[company]));case 'Payables':return d.db.then((x)=>x.rawQuery("SELECT l.name, COALESCE(SUM(ve.credit-ve.debit),0) balance FROM ledgers l LEFT JOIN voucher_entries ve ON ve.ledger_id=l.id WHERE l.company_id=? AND l.is_supplier=1 GROUP BY l.id HAVING balance<>0 ORDER BY l.name",[company]));default:return [];}}
}

