class SettingsPage extends StatelessWidget{final VoidCallback onRefresh;const SettingsPage({super.key,required this.onRefresh});@override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(16),children:[
  Card(child:ListTile(leading:const Icon(Icons.business),title:const Text('Company profile'),subtitle:FutureBuilder<List<Map<String,Object?>>>(future:AppDb.instance.query('companies'),builder:(c,s)=>Text(s.data?.isNotEmpty==true?'${s.data!.first['name']} • ${s.data!.first['gstin']??'GSTIN not set'}':'Not configured')),onTap:()=>showDialog(context:c,builder:(_)=>CompanyDialog(onSaved:onRefresh)))),
  Card(child:ListTile(leading:const Icon(Icons.backup),title:const Text('Backup database'),subtitle:const Text('Export all ERP data to a JSON file'),onTap:()=>backup(c))),
  Card(child:ListTile(leading:const Icon(Icons.restore),title:const Text('Restore database'),subtitle:const Text('Replace local data from an ERP JSON backup'),onTap:()=>restore(c))),
  Card(child:ListTile(leading:const Icon(Icons.print),title:const Text('Test invoice printing'),onTap:()=>printInvoice(null))),
  const Card(child:ListTile(leading:Icon(Icons.security),title:Text('Data safety'),subtitle:Text('Use regular backups. The app does not upload your business data to a server.'))),
  const Padding(padding:EdgeInsets.all(12),child:Text('Offline ERP • accounting + inventory + GST-ready documents • v1.0.0')),
]);
Future<void> backup(BuildContext c)async{final json=await AppDb.instance.exportJson();final uri=await FilePicker.saveFile(dialogTitle:'Save ERP backup',fileName:'offline_erp_${DateFormat('yyyyMMdd_HHmm').format(DateTime.now())}.json',bytes:utf8.encode(json));if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text(uri==null?'Backup cancelled':'Backup saved')));}
Future<void> restore(BuildContext c)async{final r=await FilePicker.pickFiles(type:FileType.custom,allowedExtensions:['json'],withData:true);if(r==null||r.files.single.bytes==null)return;final ok=await showDialog<bool>(context:c,builder:(_)=>AlertDialog(title:const Text('Restore backup?'),content:const Text('This replaces all current local ERP data. Make a backup first.'),actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('Restore'))]));if(ok==true){await AppDb.instance.importJson(utf8.decode(r.files.single.bytes!));if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('Restore complete. Restart the app if the dashboard still shows old data.')));}}
}

