class _CompanyDialogState extends State<CompanyDialog>{final name=TextEditingController(),gst=TextEditingController(),pan=TextEditingController(),state=TextEditingController(),address=TextEditingController(),phone=TextEditingController();@override Widget build(BuildContext c)=>FutureBuilder<List<Map<String,Object?>>>(future:AppDb.instance.query('companies'),builder:(c,s){final x=s.data?.isNotEmpty==true?s.data!.first:null;if(x!=null&&name.text.isEmpty){name.text='${x['name']??''}';gst.text='${x['gstin']??''}';pan.text='${x['pan']??''}';state.text='${x['state']??''}';address.text='${x['address']??''}';phone.text='${x['phone']??''}';}return AlertDialog(title:const Text('Company Profile'),content:SizedBox(width:540,child:SingleChildScrollView(child:Column(children:[f(name,'Business name'),f(gst,'GSTIN'),f(pan,'PAN'),f(state,'State'),f(address,'Address',multi:true),f(phone,'Phone')]))),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancel')),FilledButton(onPressed:save,child:const Text('Save'))]);});Widget f(TextEditingController x,String l,{bool multi=false})=>Padding(padding:const EdgeInsets.only(bottom:9),child:TextField(controller:x,maxLines:multi?3:1,decoration:InputDecoration(labelText:l,border:const OutlineInputBorder())));Future<void> save()async{final company=await cid();await AppDb.instance.update('companies',{'name':name.text,'gstin':gst.text,'pan':pan.text,'state':state.text,'address':address.text,'phone':phone.text},'id=?',[company]);widget.onSaved();if(mounted)Navigator.pop(context);}}

