class _SimpleMasterState extends State<SimpleMaster> {
  @override
  Widget build(BuildContext c) {
    return Column(children: [
      Align(
        alignment: Alignment.centerRight,
        child: Padding(
          padding: const EdgeInsets.only(right: 16, bottom: 8),
          child: FilledButton.icon(
            onPressed: () => showDialog(context: c, builder: (_) => SimpleDialogForm(table: widget.table, title: widget.title, fields: widget.fields, onSaved: widget.onRefresh)),
            icon: const Icon(Icons.add), label: Text(widget.title),
          ),
        ),
      ),
      Expanded(
        child: FutureBuilder<List<Map<String, Object?>>>(
          future: AppDb.instance.query(widget.table, orderBy: 'name'),
          builder: (c, s) {
            final rows = s.data ?? [];
            return ListView(
              children: rows.map((r) => Card(
                margin: const EdgeInsets.symmetric(horizontal: 16, vertical: 4),
                child: ListTile(
                  title: Text('${r['name']}'),
                  subtitle: Text(widget.fields.skip(1).map((f) => '${r[f] ?? ''}').join(' • ')),
                ),
              )).toList(),
            );
          },
        ),
      ),
    ]);
  }
}

class SimpleDialogForm extends StatefulWidget{final String table,title;final List<String> fields;final VoidCallback onSaved;const SimpleDialogForm({super.key,required this.table,required this.title,required this.fields,required this.onSaved});@override State<SimpleDialogForm> createState()=>_SimpleDialogFormState();}
class _SimpleDialogFormState extends State<SimpleDialogForm>{late final Map<String,TextEditingController> ctrls={for(final f in widget.fields)f:TextEditingController()};@override Widget build(BuildContext c)=>AlertDialog(title:Text('Add ${widget.title}'),content:Column(mainAxisSize:MainAxisSize.min,children:widget.fields.map((f)=>Padding(padding:const EdgeInsets.only(bottom:8),child:TextField(controller:ctrls[f],decoration:InputDecoration(labelText:f,border:const OutlineInputBorder())))).toList()),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancel')),FilledButton(onPressed:save,child:const Text('Save'))]);Future<void> save()async{final company=await cid();final data=<String,Object?>{'id':AppDb.instance.id(),'company_id':company};for(final f in widget.fields)data[f]=ctrls[f]!.text;await AppDb.instance.insert(widget.table,data);widget.onSaved();if(mounted)Navigator.pop(context);}}

class PurchaseDialogPlaceholder extends StatelessWidget{const PurchaseDialogPlaceholder({super.key});@override Widget build(BuildContext c)=>const SizedBox();}

Future<String> _ledgerId(String company,String name)async{final r=await AppDb.instance.query('ledgers',where:'company_id=? AND name=?',args:[company,name],limit:1);if(r.isEmpty)throw Exception('Ledger missing: $name');return r.first['id'] as String;}
Future<String> _voucherType(String company,String code)async{final r=await AppDb.instance.query('voucher_types',where:'company_id=? AND code=?',args:[company,code],limit:1);if(r.isEmpty)throw Exception('Voucher type missing: $code');return r.first['id'] as String;}

Future<void> printInvoice(String? invoiceId)async{
  final d=AppDb.instance;final doc=pw.Document();String title='Offline ERP';String body='';
  if(invoiceId!=null){final inv=(await d.query('sales_invoices',where:'id=?',args:[invoiceId],limit:1)).first;final customer=(await d.query('ledgers',where:'id=?',args:[inv['customer_id']],limit:1)).first;final items=await d.query('sales_invoice_items',where:'invoice_id=?',args:[invoiceId]);title='Tax Invoice ${inv['invoice_no']}';body='Customer: ${customer['name']}\nDate: ${dateText(inv['invoice_date'])}\n\n';for(final i in items){final item=(await d.query('stock_items',where:'id=?',args:[i['stock_item_id']],limit:1)).first;body+='${item['name']}  Qty ${i['quantity']} × ${money(i['rate'])} = ${money(i['total_amount'])}\n';}body+='\nTaxable: ${money(inv['taxable_amount'])}\nCGST: ${money(inv['cgst_amount'])}\nSGST: ${money(inv['sgst_amount'])}\nIGST: ${money(inv['igst_amount'])}\nTOTAL: ${money(inv['grand_total'])}';}else{body='PDF printing test\nYour invoice/report printer is connected to the app.';}
  doc.addPage(pw.MultiPage(build:(ctx)=>[pw.Header(level:0,child:pw.Text(title)),pw.Paragraph(text:body)]));await Printing.layoutPdf(onLayout:(format)async=>doc.save());
}
